      vec3(0.001, 0.000, 0.014),
      vec3(0.213, 0.066, 0.333),
      vec3(0.549, 0.118, 0.360),
      vec3(0.855, 0.180, 0.110),
      vec3(0.987, 0.991, 0.749)
