      vec3(0.002, 0.000, 0.014),
      vec3(0.273, 0.074, 0.458),
      vec3(0.578, 0.148, 0.404),
      vec3(0.865, 0.317, 0.118),
      vec3(0.988, 0.998, 0.645)
